-- 20261125012540 ascent_strict_player_no_repeats_and_global_novelty
do $patch$ declare d text;n text;begin
select pg_get_functiondef('ascent_game.generate_varied_climb(text,uuid)'::regprocedure) into d;
n:=replace(d,'prior_signatures text[];','prior_signatures text[]; issued_signatures text[];');
n:=replace(n,' for i in 0..4 loop',' select coalesce(array_agg(distinct ascent_game.pitch_signature(p)),''{}'') into issued_signatures from ascent_game.circuits c cross join lateral jsonb_array_elements(c.boards) p where c.route_id<>seed;
 for i in 0..4 loop');
n:=replace(n,'and b.target<>all(used_targets)','and b.target<>all(used_targets) and ascent_game.pitch_signature(jsonb_build_object(''clues'',b.clues))<>all(prior_signatures)');
n:=replace(n,'order by (ascent_game.pitch_signature(jsonb_build_object(''clues'',b.clues))=any(prior_signatures)),','order by (ascent_game.pitch_signature(jsonb_build_object(''clues'',b.clues))=any(issued_signatures)),');
-- Penalize near-identical boards too, independently of shuffle/order and player ticket.
n:=replace(n,'(b.phrase_count<>required_phrases),coalesce(u.n,0),','(select count(*) from ascent_game.circuits cc cross join lateral jsonb_array_elements(cc.boards) pp where cc.route_id<>seed and (select count(*) from jsonb_array_elements_text(pp->''clues'') x where x=any(b.clues))>=5),(b.phrase_count<>required_phrases),coalesce(u.n,0),');
if n=d or n not like '%<>all(prior_signatures)%' or n not like '%=any(issued_signatures)%' then raise exception 'Repeat guard patch mismatch';end if;
execute n;
end;$patch$;

