-- Direct links are reciprocal when the underlying association is explicitly established.
insert into ascent_game.association_scores_v7(clue,word,strength,reason)
select s.word,s.clue,least(s.strength,95),s.reason from ascent_game.association_scores_v7 s
where s.strength>=90 and s.reason not like 'Semantic link via %' and s.reason not like 'Related through %' and s.clue<>s.word
and exists(select 1 from ascent_game.rich_tier_boards_v7 b where b.semantic_verified and s.word=any(b.clues))
on conflict(clue,word) do nothing;
insert into ascent_game.spelling_vocabulary select distinct word from ascent_game.association_scores_v7 on conflict do nothing;


