-- Exact equivalent words are evaluated together even if one spelling already matched some clues.
create function ascent_game.complete_equivalent_answers(clues text[],guess text,known jsonb) returns jsonb language sql stable set search_path='' as $fn$
 with equivalent as (
 select distinct b.word from ascent_game.equivalent_answers a join ascent_game.equivalent_answers b using(group_key) where a.word=guess and b.word<>all(clues)
 ), inferred as (
 select distinct on(s.clue) s.clue,s.reason||' (equivalent answer: '||s.word||') ('||s.strength||'% match)' reason
 from ascent_game.association_scores_v7 s join equivalent e on e.word=s.word where s.clue=any(clues) and s.strength>=65 and not known ? s.clue order by s.clue,s.strength desc,s.word
 )
 select known||coalesce((select jsonb_object_agg(clue,reason) from inferred),'{}')
$fn$;
revoke all on function ascent_game.complete_equivalent_answers(text[],text,jsonb) from public,anon,authenticated;
do $patch$ declare d text;n text;begin
 select pg_get_functiondef('ascent_game.semantic_complete_guess(text[],text,uuid,jsonb)'::regprocedure) into d;
 n:=replace(d,' missing:=array(select c from unnest(clues) c where not known ? c);',' known:=ascent_game.complete_equivalent_answers(clues,corrected,known);
 missing:=array(select c from unnest(clues) c where not known ? c);');
 if n=d then raise exception 'Complete equivalent answers patch mismatch';end if;execute n;
end;$patch$;
create or replace function ascent_game.preview_registered_guess(clues text[],guess text) returns jsonb language sql stable set search_path='' as $fn$
 with base as (select ascent_game.complete_equivalent_answers(clues,guess,ascent_game.match_guess(7,clues,guess)) known), v as (select embedding from ascent_game.semantic_word_vectors where word=guess)
 select known||coalesce((select ascent_game.vector_clue_matches(array(select c from unnest(clues) c where not known ? c),guess,embedding) from v where (select enabled from ascent_game.semantic_config where singleton)), '{}'::jsonb) from base
$fn$;
insert into ascent_game.spelling_vocabulary select word from ascent_game.equivalent_answers on conflict do nothing;


